/**
 * Kingdom Conquest III - Tactical Lineup & Troop Capacity Engine
 *
 * Rules:
 * 1. Lineup Point Budget: Max 15 points per lineup.
 * 2. Troop Capacity: Hard base cap of 9,999 prior to Intelligence, Research, and Skills.
 * 3. Card-Driven Troop Creation: Troops are generated by the collected cards in the deck.
 */

import { CommanderCard, UnitUpgradeCard, ResearchTech, CardSkill } from './types';

export const MAX_LINEUP_POINTS = 15;
export const BASE_TROOP_CAP = 9999;

export interface TroopCapBreakdown {
  baseCap: number; // Exactly 9999
  intel: number;
  intelBonus: number; // Scaled by commander.intel
  researchBonus: number; // Scaled by academy techs
  skillBonus: number; // Scaled by equipped & signature skills
  totalCap: number; // baseCap + intelBonus + researchBonus + skillBonus
}

/**
 * Calculates the exact effective troop capacity for a commander and active empire state.
 * Hard base cap of 9999 prior to intelligence, research, and skills.
 */
export function calculateTroopCapacity(
  commander: CommanderCard,
  techs: ResearchTech[] = []
): TroopCapBreakdown {
  // Intel Factor: Every 100 INT grants ~85 extra troop capacity
  const intel = commander.intel || 1000;
  const intelBonus = Math.round((intel / 100) * 85);

  // Research Factor: Academy military logistics and grand cohort research
  const researchBonus = techs.reduce((acc, tech) => {
    return acc + (tech.troopCapBonus || 0) * (tech.level || 1);
  }, 0);

  // Skill Factor: Equippable and signature skills granting troop numbers
  let skillBonus = 0;
  if (commander.signatureSkill?.troopCapBonus) {
    skillBonus += commander.signatureSkill.troopCapBonus;
  }
  if (commander.equippedSkills) {
    commander.equippedSkills.forEach((skill) => {
      if (skill?.troopCapBonus) {
        skillBonus += skill.troopCapBonus;
      }
    });
  }

  const totalCap = BASE_TROOP_CAP + intelBonus + researchBonus + skillBonus;

  return {
    baseCap: BASE_TROOP_CAP,
    intel,
    intelBonus,
    researchBonus,
    skillBonus,
    totalCap,
  };
}

/**
 * Calculates total points consumed by a lineup.
 * Strict maximum of 15 points.
 */
export function calculateLineupPoints(
  commander?: CommanderCard | null,
  battalionCard?: UnitUpgradeCard | null,
  supportCard?: UnitUpgradeCard | null
): {
  totalPoints: number;
  maxPoints: number;
  isOverBudget: boolean;
  remainingPoints: number;
} {
  let pts = 0;
  if (commander?.cost) pts += commander.cost;
  if (battalionCard?.cost) pts += battalionCard.cost;
  if (supportCard?.cost) pts += supportCard.cost;

  return {
    totalPoints: pts,
    maxPoints: MAX_LINEUP_POINTS,
    isOverBudget: pts > MAX_LINEUP_POINTS,
    remainingPoints: Math.max(0, MAX_LINEUP_POINTS - pts),
  };
}

export interface CardTroopYields {
  legionnaire: number;
  archer: number;
  gryphon: number;
  catapult: number;
  totalPerCycle: number;
}

/**
 * Calculates total troops generated per cycle by all collected cards in the deck.
 */
export function calculateCollectedCardTroopYields(
  commanders: CommanderCard[],
  unitCards: UnitUpgradeCard[]
): CardTroopYields {
  const yields: CardTroopYields = {
    legionnaire: 0,
    archer: 0,
    gryphon: 0,
    catapult: 0,
    totalPerCycle: 0,
  };

  commanders.forEach((card) => {
    if (card.troopGeneration) {
      const type = card.troopGeneration.troopType;
      const count = card.troopGeneration.yieldPerCycle;
      yields[type] = (yields[type] || 0) + count;
      yields.totalPerCycle += count;
    }
  });

  unitCards.forEach((card) => {
    if (card.troopGeneration) {
      const type = card.troopGeneration.troopType;
      const count = card.troopGeneration.yieldPerCycle;
      yields[type] = (yields[type] || 0) + count;
      yields.totalPerCycle += count;
    }
  });

  return yields;
}
